options.customCss:
:root {
  /* Modern Purple Gradient Theme */
  --chat--color-primary: #667eea;
  --chat--color-primary-shade-50: #5a6fd8;
  --chat--color-primary-shade-100: #4e5fc6;
  --chat--color-secondary: #764ba2;
  --chat--color-secondary-shade-50: #6a4391;
  --chat--color-white: #ffffff;
  --chat--color-light: #f8fafc;
  --chat--color-light-shade-50: #e2e8f0;
  --chat--color-light-shade-100: #cbd5e1;
  --chat--color-medium: #94a3b8;
  --chat--color-dark: #1e293b;
  --chat--color-disabled: #94a3b8;
  --chat--color-typing: #475569;

  /* Modern Font */
  --chat--font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;

  /* Spacing & Borders */
  --chat--spacing: 1.25rem;
  --chat--border-radius: 12px;
  --chat--transition-duration: 0.2s;

  /* Window Dimensions */
  --chat--window--width: 420px;
  --chat--window--height: 650px;
  --chat--window--bottom: 1.5rem;
  --chat--window--right: 1.5rem;
  --chat--window--z-index: 9999;
  --chat--window--border: none;
  --chat--window--border-radius: 20px;
  --chat--window--margin-bottom: var(--chat--spacing);

  /* Header - Purple Gradient */
  --chat--header-height: auto;
  --chat--header--padding: 1.75rem;
  --chat--header--background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  --chat--header--color: var(--chat--color-white);
  --chat--header--border-top: none;
  --chat--header--border-bottom: none;
  --chat--header--border-left: none;
  --chat--header--border-right: none;
  --chat--heading--font-size: 1.5rem;
  --chat--subtitle--font-size: 0.95rem;
  --chat--subtitle--line-height: 1.5;

  /* Message Styles */
  --chat--message--font-size: 0.95rem;
  --chat--message--padding: 1rem 1.25rem;
  --chat--message--border-radius: 16px;
  --chat--message-line-height: 1.6;
  --chat--message--margin-bottom: 1rem;
  --chat--message--bot--background: var(--chat--color-white);
  --chat--message--bot--color: var(--chat--color-dark);
  --chat--message--bot--border: 1px solid var(--chat--color-light-shade-50);
  --chat--message--user--background: #667eea;
  --chat--message--user--color: #ffffff;
  --chat--message--user--border: none;
  --chat--message--pre--background: rgba(0, 0, 0, 0.05);
  --chat--messages-list--padding: 1.5rem;

  /* Toggle Button */
  --chat--toggle--size: 64px;
  --chat--toggle--width: var(--chat--toggle--size);
  --chat--toggle--height: var(--chat--toggle--size);
  --chat--toggle--border-radius: 50%;
  --chat--toggle--background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  --chat--toggle--hover--background: #5a6fd8;
  --chat--toggle--active--background: #4e5fc6;
  --chat--toggle--color: var(--chat--color-white);

  /* Input Area */
  --chat--textarea--height: 52px;
  --chat--textarea--max-height: 200px;
  --chat--input--font-size: 0.95rem;
  --chat--input--border: 2px solid var(--chat--color-light-shade-50);
  --chat--input--border-radius: 12px;
  --chat--input--padding: 1rem 1.25rem;
  --chat--input--background: var(--chat--color-white);
  --chat--input--text-color: var(--chat--color-dark);
  --chat--input--line-height: 1.5;
  --chat--input--placeholder--font-size: var(--chat--input--font-size);
  --chat--input--border-active: 2px solid #667eea;
  --chat--input--left--panel--width: 2.5rem;

  /* Button Styles */
  --chat--button--color: var(--chat--color-white);
  --chat--button--background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  --chat--button--padding: 0.75rem 1.5rem;
  --chat--button--border-radius: 10px;
  --chat--button--hover--color: var(--chat--color-white);
  --chat--button--hover--background: #5a6fd8;
  --chat--close--button--color-hover: var(--chat--color-primary);

  /* Send Button */
  --chat--input--send--button--background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  --chat--input--send--button--color: var(--chat--color-white);
  --chat--input--send--button--background-hover: #5a6fd8;
  --chat--input--send--button--color-hover: var(--chat--color-white);
  --chat--input--file--button--background: var(--chat--color-white);
  --chat--input--file--button--color: #667eea;
  --chat--input--file--button--background-hover: var(--chat--color-light);
  --chat--input--file--button--color-hover: #5a6fd8;
  --chat--files-spacing: 0.5rem;

  /* Body and Footer */
  --chat--body--background: var(--chat--color-light);
  --chat--footer--background: var(--chat--color-white);
  --chat--footer--color: var(--chat--color-dark);
}

/* Custom Class Overrides */
.chat-message {
  max-width: 75%;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.05);
}

.chat-window {
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.25);
}

/* Force proper user message styling - try all possible class names */
.chat-message-user,
.chat-message.user,
[data-role="user"],
.message-user {
  background: #667eea !important;
  color: #ffffff !important;
}
